
// We control scroll position ourselves on every navigation (see swapContent)
// -- don't let the browser's own back/forward scroll memory fight that.
history.scrollRestoration = "manual";

// Accordion tree: opening a branch closes its sibling branches at the same
// level, so at most one root-to-leaf path is ever expanded at once. "toggle"
// does not bubble, so this must be a capturing listener on an ancestor.
document.addEventListener("toggle", function (e) {
  const el = e.target;
  if (!(el instanceof HTMLDetailsElement) || !el.classList.contains("tree-node") || !el.open) return;
  const parent = el.parentElement;
  if (!parent) return;
  Array.from(parent.children).forEach((sib) => {
    if (sib !== el && sib.tagName === "DETAILS" && sib.open) sib.open = false;
  });
}, true);

function domainClassOf(body) {
  return Array.from(body.classList).find(function (c) { return c.indexOf("domain-") === 0; }) || null;
}

// Client-side navigation: fetch the target page, swap only .content and the
// footer nav, never touch/reload navbar or the sidebar (so its scroll
// position and expanded tree branches stay put -- the whole point of a
// "static" left column) -- UNLESS the fetched page belongs to the other
// domain, in which case the sidebar is an entirely different book's tree and
// gets replaced wholesale instead (no "keep scroll position" case makes
// sense when crossing books).
function swapContent(html, url) {
  const doc = new DOMParser().parseFromString(html, "text/html");
  const newContent = doc.querySelector("main.content");
  const current = document.querySelector("main.content");
  if (!newContent || !current) { location.href = url; return; }

  const newDomain = domainClassOf(doc.body);
  const curDomain = domainClassOf(document.body);
  if (newDomain && newDomain !== curDomain) {
    document.body.classList.remove(curDomain);
    document.body.classList.add(newDomain);
    // The sidebar now holds both the domain tabs and the tree (see
    // build-site.js's pageShell) -- swapping its whole innerHTML carries
    // over the new domain's correct active-tab state from the
    // server-rendered page too, so no separate .domain-switch
    // active-class toggle is needed here anymore.
    const newSidebar = doc.querySelector(".filetree-sidebar");
    const curSidebar = document.querySelector(".filetree-sidebar");
    if (newSidebar && curSidebar) curSidebar.innerHTML = newSidebar.innerHTML;
  }

  current.innerHTML = newContent.innerHTML;
  document.title = doc.title;

  const newFooter = doc.querySelector("#page-footer-nav");
  const currentFooter = document.querySelector("#page-footer-nav");
  if (newFooter && currentFooter) currentFooter.innerHTML = newFooter.innerHTML;

  document.querySelectorAll(".filetree-sidebar .active-note").forEach((el) => el.classList.remove("active-note"));
  // A synthetic top-level node (e.g. Terrinoth's "Introduction") links to the
  // same URL as its own first real child -- querySelector would only ever
  // find the FIRST of the two matching <a> tags, leaving the other stuck
  // unmarked no matter which of the (identical) hrefs the tree actually shows.
  // querySelectorAll + marking every match (and walking up from each one)
  // covers both, same as the server-rendered tree already does.
  // Sidebar entries never carry a "#heading-id" fragment of their own (they
  // always link at the plain article), so a shortcut's "#anchor" URL has to
  // be stripped back down to just the path first, or this lookup silently
  // matches nothing at all and the sidebar shows no active section.
  const urlNoHash = url.split("#")[0];
  const activeLinks = document.querySelectorAll('.filetree-sidebar a[href="' + urlNoHash + '"]');
  const keepOpen = new Set();
  activeLinks.forEach(function (activeLink, i) {
    const holder = activeLink.closest(".notelink");
    if (holder) holder.classList.add("active-note");
    let d = activeLink.closest("details");
    while (d) {
      d.open = true;
      keepOpen.add(d);
      // The whole open path -- current article + every ancestor -- shares
      // the same active-note highlight (mirrors the server-rendered tree).
      const summary = d.querySelector(":scope > summary.notelink");
      if (summary) summary.classList.add("active-note");
      d = d.parentElement ? d.parentElement.closest("details") : null;
    }
    if (i === 0) activeLink.scrollIntoView({ block: "nearest" });
  });
  // Client-side swaps never went through the server's single-path render, so
  // any branch left open from before that isn't on the new active path (e.g.
  // a whole other top-level section) has to be closed explicitly here too.
  document.querySelectorAll(".filetree-sidebar details.tree-node[open]").forEach((d) => {
    if (!keepOpen.has(d)) d.open = false;
  });

  // A "#heading-id" fragment (e.g. the home portal's Shortcuts column, see
  // addHeadingIds/resolveShortcut in build-site.js) has to be resolved by
  // hand here -- client-side swaps never trigger the browser's own native
  // fragment-scroll (that only fires on a real navigation/hashchange, and
  // preventDefault() in the click handler below suppresses exactly that).
  // Without this, every heading-anchored link -- including a shortcut that
  // points at a specific table -- silently landed on the plain top of the
  // article instead, indistinguishable from a link with no fragment at all.
  const hashIdx = url.indexOf("#");
  const hash = hashIdx === -1 ? "" : url.slice(hashIdx + 1);
  const target = hash ? document.getElementById(hash) : null;
  if (target) {
    // A cold (real) navigation to a fragment inside a closed <details>
    // auto-opens it natively in every modern browser -- but this is a
    // client-side swap, no real fragment navigation ever happens, so that
    // native behavior never fires either. Force every ancestor <details>
    // open by hand instead (Nutzerwunsch 2026-08-02: "Alle Container,
    // Tables, Container in Tables etc. sollen aufgeklappt sein, wenn man per
    // Search-Box zu ihnen kommt") -- walks up however many levels deep the
    // target sits (a table's own caption inside a container-accordion, a
    // container inside some future nested nesting, etc.), not just one.
    let d = target.closest("details");
    while (d) {
      d.open = true;
      d = d.parentElement ? d.parentElement.closest("details") : null;
    }
    target.scrollIntoView({ block: "start" });
    return;
  }

  // Reset scroll on every plausible scroll container -- which one actually
  // holds the page's scroll offset depends on the inherited Obsidian-app
  // CSS cascade, so cover window/html/body all at once rather than guess.
  window.scrollTo(0, 0);
  document.documentElement.scrollTop = 0;
  document.body.scrollTop = 0;
  current.scrollTop = 0;
}

function navigate(url, push) {
  return fetch(url)
    .then((r) => r.text())
    .then((html) => {
      swapContent(html, url);
      if (push) history.pushState({ url: url }, "", url);
    })
    .catch(() => { location.href = url; });
}

document.addEventListener("click", function (e) {
  const a = e.target.closest("a");
  if (!a) return;
  const href = a.getAttribute("href");
  if (!href || !href.startsWith("/") || a.target === "_blank") return;
  if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
  e.preventDefault();

  // A tree-node label click always toggles ITS OWN branch closed if it was
  // already open -- whether that's because you're already on that exact
  // page, or because you navigated into one of its descendants (making it
  // an already-open ancestor). Capture the pre-click state before anything
  // (navigation, the active-path re-render) can change it.
  const summary = a.closest("summary");
  const ownDetails = summary ? summary.closest("details") : null;
  const wasOpen = ownDetails ? ownDetails.open : false;

  if (href === location.pathname) {
    // Already on this page -- nothing to fetch, just toggle.
    if (ownDetails) ownDetails.open = !wasOpen;
    return;
  }

  navigate(href, true).then(() => {
    // swapContent() always force-opens the newly active node's own branch
    // to reveal the new position -- override that back closed if the user
    // just clicked an already-expanded branch (same "click open -> close"
    // rule as the same-page case above).
    if (ownDetails && wasOpen) ownDetails.open = false;
  });
});

window.addEventListener("popstate", function () {
  // location.pathname alone drops the "#heading-id" fragment (that lives in
  // location.hash instead) -- without appending it back, back/forward past a
  // shortcut's anchor link would re-land on the plain article top.
  navigate(location.pathname + location.hash, false);
});

// ArrowLeft/ArrowRight page through the whole book front-to-back (flat
// depth-first order, see FLAT_ORDERS/flattenOrder in build-site.js) -- not
// just prev/next among siblings at the current depth (that's the footer
// nav's job). Which book's order applies is read from the current domain
// class at keypress time (not fixed at page load), so it keeps working
// correctly across a client-side domain switch. Ignored with any modifier
// held, or while a form field has focus, so it never fights normal
// text-selection/editing use of the arrow keys.
