(function () {
  const input = document.querySelector(".search-input");
  const results = document.querySelector(".search-results");
  if (!input || !results) return;

  function escapeHtml(s) {
    return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  // -1 = nothing highlighted yet (plain hover/Enter-picks-first still
  // works); ArrowDown/ArrowUp move a "active" class among the result <a>
  // tags without touching input focus, mirroring a standard combobox.
  let activeIndex = -1;

  function setActive(idx) {
    const items = Array.from(results.querySelectorAll(".search-result-item"));
    if (!items.length) return;
    activeIndex = Math.max(0, Math.min(idx, items.length - 1));
    items.forEach((el, i) => el.classList.toggle("active", i === activeIndex));
    items[activeIndex].scrollIntoView({ block: "nearest" });
  }

  function render(query) {
    const q = query.trim().toLowerCase();
    activeIndex = -1;
    if (!q) {
      results.hidden = true;
      results.innerHTML = "";
      return;
    }
    const starts = [];
    const contains = [];
    for (const item of SEARCH_INDEX) {
      const i = item.title.toLowerCase().indexOf(q);
      if (i === -1) continue;
      (i === 0 ? starts : contains).push(item);
    }
    const matches = starts.concat(contains).slice(0, 15);
    results.innerHTML = matches.length
      ? matches.map((m) => '<a class="search-result-item" href="' + m.url + '">' + m.titleHtml + '<span class="search-result-domain">' + escapeHtml(m.domain) + "</span></a>").join("")
      : '<div class="search-no-results">No matches</div>';
    results.hidden = false;
  }

  input.addEventListener("input", function () { render(input.value); });
  input.addEventListener("focus", function () { if (input.value) render(input.value); });
  input.addEventListener("keydown", function (e) {
    if (e.key === "Escape") { results.hidden = true; input.blur(); return; }
    if (e.key === "ArrowDown") { e.preventDefault(); setActive(activeIndex + 1); return; }
    if (e.key === "ArrowUp") { e.preventDefault(); setActive(activeIndex - 1); return; }
    if (e.key === "Enter") {
      const items = results.querySelectorAll(".search-result-item");
      const pick = activeIndex >= 0 ? items[activeIndex] : items[0];
      if (pick) pick.click();
    }
  });
  // Clears the field once a result is actually followed -- both a mouse
  // click and the Enter-key handler above end up dispatching a real click
  // on the result <a>, so this single listener covers both.
  results.addEventListener("click", function () {
    input.value = "";
    results.hidden = true;
    results.innerHTML = "";
  });
  document.addEventListener("click", function (e) {
    if (!e.target.closest(".navbar-search")) results.hidden = true;
  });
})();

// ---- Cookie helpers (Nutzerwunsch 2026-07-30, explicit and emphatic:
// persistence for theme/language/font-size is cookie-based, not
// localStorage) -- 1-year expiry, path=/ so every page under the domain
// reads the same cookie regardless of which article set it.
const COOKIE_MAX_AGE = 60 * 60 * 24 * 365;
function setCookie(name, value) {
  document.cookie = name + "=" + encodeURIComponent(value) + "; path=/; max-age=" + COOKIE_MAX_AGE + "; SameSite=Lax";
}
function getCookie(name) {
  const m = document.cookie.match("(?:^|; )" + name + "=([^;]*)");
  return m ? decodeURIComponent(m[1]) : null;
}

// Light/dark toggle (top-right glyph button). The initial theme is already
// applied by the inline script right after <body> (see pageShell) -- before
// this file even loads -- so all that's left here is reacting to clicks.
// The domain switch (top-left logos) needs no dedicated handler of its own
// -- it's a real link now (see HOME_URLS in build-site.js), handled by the
// generic click listener above like any other nav link.
const THEME_STORAGE_KEY = "theme";
const themeToggle = document.querySelector(".theme-toggle");
if (themeToggle) {
  themeToggle.addEventListener("click", function () {
    const next = document.body.classList.contains("theme-dark") ? "light" : "dark";
    document.body.classList.remove("theme-light", "theme-dark");
    document.body.classList.add("theme-" + next);
    setCookie(THEME_STORAGE_KEY, next);
  });
}

// Language toggle (placeholder, Nutzerwunsch 2026-07-29): purely cosmetic
// for now -- there's no German content to actually switch to yet, so a
// click just swaps the flag glyph and nothing else. Defaults to the German
// flag (see the button's initial content in build-site.js's pageShell)
// since it represents "switch TO this language", and the site's actual
// content is all English already -- no persistence, since there's no real
// state behind it to remember yet (once real German content exists, this
// gets the same cookie treatment as theme/font-scale).
const langToggle = document.querySelector(".lang-toggle");
if (langToggle) {
  langToggle.addEventListener("click", function () {
    langToggle.textContent = langToggle.textContent === "🇩🇪" ? "🇺🇸" : "🇩🇪";
  });
}

// Floating overlay layout toggle (Nutzerwunsch 2026-07-31): one central
// button, not per-container -- swaps .filetree-sidebar/.navbar/.page-footer-
// nav from their normal fixed layout into edge-anchored overlays that slide
// in on hover (see body.layout-floating in site.scss). Persisted the same
// way as theme/fontScale; the inline pre-body script (pageShell) applies it
// before first paint to avoid a flash of the wrong layout.
const layoutToggle = document.querySelector(".layout-toggle");
if (layoutToggle) {
  layoutToggle.addEventListener("click", function () {
    const next = !document.body.classList.contains("layout-floating");
    document.body.classList.toggle("layout-floating", next);
    setCookie("layoutFloating", next ? "1" : "0");
  });
}

// Site-wide font-size buttons (Nutzerwunsch 2026-07-30): every content
// font-size in site.scss is expressed in em/pt-on-top-of-em relative to
// body's own font-size, so scaling just that one root value scales the
// whole site proportionally (headings, tables, lists) while leaving the
// small fixed pt calibration offsets -- see the .domain-genesys/.domain-
// terrinoth h1-h6 formulas -- essentially untouched, which is what keeps
// them working as font-family size compensation instead of also scaling.
// --font-scale is applied as an inline style (not a class) so it can hold
// an arbitrary numeric value; the initial value is set by the same inline
// pre-body script that applies the theme (see pageShell), to avoid a
// flash of default-sized text before this file loads.
const FONT_SCALE_KEY = "fontScale";
// FONT_SCALE_MIN lowered from 0.8 to 0.6 (Nutzerwunsch 2026-07-31: "Minus
// soll noch zwei Stufen kleiner möglich sein") -- two more FONT_SCALE_STEPs
// below the old floor. Keep in sync with the hardcoded 0.6 in the inline
// pre-body FOUC-prevention script below (pageShell), which duplicates this
// clamp before this script has even loaded.
const FONT_SCALE_MIN = 0.6;
const FONT_SCALE_MAX = 1.4;
const FONT_SCALE_STEP = 0.1;
function getFontScale() {
  const v = parseFloat(getCookie(FONT_SCALE_KEY));
  return !v || v < FONT_SCALE_MIN || v > FONT_SCALE_MAX ? 1 : v;
}
function setFontScale(v) {
  const clamped = Math.min(FONT_SCALE_MAX, Math.max(FONT_SCALE_MIN, v)).toFixed(2);
  document.documentElement.style.setProperty("--font-scale", clamped);
  setCookie(FONT_SCALE_KEY, clamped);
}
const fontDecrease = document.querySelector(".font-decrease");
const fontIncrease = document.querySelector(".font-increase");
// Disable +/- at their respective limits (Nutzerwunsch 2026-07-31) -- run
// once on load (cookie may already be at a limit) and again after every
// click, since setFontScale's own clamp is what actually decides whether a
// click moved the value at all.
function updateFontButtonState() {
  const scale = getFontScale();
  if (fontDecrease) fontDecrease.disabled = scale <= FONT_SCALE_MIN;
  if (fontIncrease) fontIncrease.disabled = scale >= FONT_SCALE_MAX;
}
updateFontButtonState();
if (fontDecrease) fontDecrease.addEventListener("click", function () { setFontScale(getFontScale() - FONT_SCALE_STEP); updateFontButtonState(); });
if (fontIncrease) fontIncrease.addEventListener("click", function () { setFontScale(getFontScale() + FONT_SCALE_STEP); updateFontButtonState(); });

// ---- Skills overview filter (Nutzerwunsch 2026-07-31, Genesys page only --
// see buildSkillsOverviewHtml in build-site.js) ----
// Delegated on "document" rather than queried once at load: this page (like
// any other) can be reached via the SPA client-side navigate() above, which
// only swaps main.content's innerHTML -- a listener bound directly to
// elements present at initial script-load time would miss controls that
// arrive later via a swap.
function applySkillsFilter(root) {
  const select = root.querySelector(".skills-setting-select");
  const magicBox = root.querySelector(".skills-magic-checkbox");
  const table = root.querySelector(".overview-table");
  if (!select || !magicBox || !table) return;
  const setting = select.value;
  const magicOn = magicBox.checked;
  table.querySelectorAll("tbody tr").forEach(function (tr) {
    const visible = tr.dataset.magic === "1"
      ? magicOn
      : (tr.dataset.settings || "").split("|").some((s) => s === "All" || s === setting);
    tr.hidden = !visible;
  });
}
document.addEventListener("change", function (e) {
  const root = e.target.closest(".skills-overview");
  if (!root) return;
  if (e.target.classList.contains("skills-setting-select")) {
    // Changing the Setting always resets Magic Rules to its setting-specific
    // default (checked for Fantasy, unchecked otherwise) -- Nutzerwunsch
    // 2026-07-31, an explicit override of whatever the checkbox was set to.
    const magicBox = root.querySelector(".skills-magic-checkbox");
    if (magicBox) magicBox.checked = e.target.value === "Fantasy";
  }
  if (e.target.classList.contains("skills-setting-select") || e.target.classList.contains("skills-magic-checkbox")) {
    applySkillsFilter(root);
  }
});

// A click anywhere in an overview-table row navigates the same as clicking
// its own name link (Nutzerwunsch 2026-07-31) -- ignored when the click
// already landed on the link itself (that's the generic <a> click handler's
// job, and synthetically re-clicking it here would double-navigate).
// link.click() dispatches a fresh click on the <a>, which bubbles back up
// into that same generic handler above for proper SPA navigation, not a hard
// page reload.
document.addEventListener("click", function (e) {
  const tr = e.target.closest(".overview-table tbody tr");
  if (!tr || e.target.closest("a")) return;
  const link = tr.querySelector("a");
  if (link) link.click();
});

// Sortable column headers, any overview table (Nutzerwunsch 2026-07-31):
// clicking a sortable column (Skills: Name/Characteristic/Group; Talents:
// Name/Tier/Activation/Ranked -- Page and Description are always plain)
// cycles that column asc -> desc -> off. Only one column is ever active at a
// time -- clicking a different header always starts it fresh at "asc" and
// resets the rest. "off" restores the table's original default order
// (already alphabetical-by-name) via each row's own data-idx, set at build
// time -- see buildOverviewTableHead/buildSkillsOverviewHtml/
// buildTalentsOverviewHtml in build-site.js.
document.addEventListener("click", function (e) {
  const th = e.target.closest(".overview-table th.sortable");
  if (!th) return;
  const headerCells = Array.from(th.parentElement.children);
  const next = th.dataset.sort === "asc" ? "desc" : th.dataset.sort === "desc" ? "" : "asc";
  headerCells.forEach(function (h) {
    const active = h === th;
    h.dataset.sort = active ? next : "";
    const indicator = h.querySelector(".sort-indicator");
    if (indicator) indicator.textContent = active ? (next === "asc" ? " ▴" : next === "desc" ? " ▾" : "") : "";
  });
  const table = th.closest("table");
  const tbody = table.querySelector("tbody");
  const colIndex = headerCells.indexOf(th);
  const rows = Array.from(tbody.querySelectorAll("tr"));
  rows.sort(function (a, b) {
    if (next === "") return Number(a.dataset.idx) - Number(b.dataset.idx);
    const av = a.children[colIndex].textContent.trim().toLowerCase();
    const bv = b.children[colIndex].textContent.trim().toLowerCase();
    if (av === bv) return Number(a.dataset.idx) - Number(b.dataset.idx);
    const cmp = av < bv ? -1 : 1;
    return next === "asc" ? cmp : -cmp;
  });
  rows.forEach(function (r) { tbody.appendChild(r); });
});
